use std::path::Path;
use std::process::Command;
use std::time::Duration;

use wait_timeout::ChildExt;

use crate::config::{uc_config_path, uc_min_results, uc_timeout_ms};

/// Result of a `uc retrieve` invocation.
pub struct UcResult {
    pub lines: Vec<String>,
    pub fallback_reason: Option<String>,
}

/// Options for controlling the `uc retrieve` invocation.
pub struct UcOptions {
    pub timeout_ms: u64,
    pub min_results: usize,
}

pub struct UcRetriever {
    opts: UcOptions,
}

impl Default for UcOptions {
    fn default() -> Self {
        Self {
            timeout_ms: uc_timeout_ms(),
            min_results: uc_min_results(),
        }
    }
}

impl UcRetriever {
    pub fn new(opts: UcOptions) -> Self {
        Self { opts }
    }

    pub fn retrieve(&self, query: &str, top_k: usize) -> UcResult {
        if !is_available() {
            return UcResult {
                lines: vec![],
                fallback_reason: Some("uc is unavailable".to_string()),
            };
        }
        retrieve_impl(query, top_k, &self.opts, &uc_config_path())
    }

    pub fn min_results(&self) -> usize {
        self.opts.min_results
    }
}

/// Check whether `uc` is available (binary on PATH + config file exists).
pub fn is_available() -> bool {
    which("uc") && uc_config_path().exists()
}

/// Inner implementation that also accepts a config path (for testing).
fn retrieve_impl(query: &str, top_k: usize, opts: &UcOptions, config_path: &Path) -> UcResult {
    let child = Command::new("uc")
        .arg("-c")
        .arg(config_path)
        .arg("retrieve")
        .arg(query)
        .arg("--top-k")
        .arg(top_k.to_string())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .spawn();

    let mut child = match child {
        Ok(c) => c,
        Err(e) => {
            return UcResult {
                lines: vec![],
                fallback_reason: Some(format!("uc spawn failed: {e}")),
            };
        }
    };

//! Hybrid search combining vector similarity and keyword matching via RRF.
#![allow(clippy::missing_errors_doc)]

use std::collections::HashMap;

use anyhow::Result;

use crate::memory_index::store::MemoryStore;
use crate::memory_index::types::{MemoryChunk, SearchResult, SearchSource};

/// Reciprocal Rank Fusion constant (controls rank sensitivity).
const RRF_K: f32 = 60.0;

/// Perform hybrid search combining vector similarity and keyword matching.
///
/// Runs vector search (limit×2) and keyword search (limit), then merges
/// results using Reciprocal Rank Fusion.
pub fn hybrid_search(
    store: &MemoryStore,
    query: &str,
    query_embedding: &[f32],
    limit: usize,
) -> Result<Vec<SearchResult>> {
    let vector_results = store.vector_search(query_embedding, limit * 2)?;
    let keyword_results = store.keyword_search(query, limit)?;
    let merged = reciprocal_rank_fusion(&vector_results, &keyword_results);
    Ok(merged.into_iter().take(limit).collect())
}

/// Merge two ranked lists using Reciprocal Rank Fusion.
///
/// `RRF(d) = Σ 1/(k + rank)` where k=60 and rank is 1-based.
fn reciprocal_rank_fusion(
    vector_results: &[(MemoryChunk, f32)],
    keyword_results: &[(MemoryChunk, f32)],
) -> Vec<SearchResult> {
    let mut scores: HashMap<String, (f32, MemoryChunk, SearchSource)> = HashMap::new();

    for (rank, (chunk, _)) in vector_results.iter().enumerate() {
        let rrf_score = 1.0 / (RRF_K + (rank + 1) as f32);
        scores
            .entry(chunk.id.clone())
            .and_modify(|(s, _, src)| {
                *s += rrf_score;
                *src = SearchSource::Hybrid;
            })
            .or_insert_with(|| (rrf_score, chunk.clone(), SearchSource::Vector));
    }

    for (rank, (chunk, _)) in keyword_results.iter().enumerate() {
        let rrf_score = 1.0 / (RRF_K + (rank + 1) as f32);
        scores
            .entry(chunk.id.clone())
            .and_modify(|(s, _, src)| {
                *s += rrf_score;
                *src = SearchSource::Hybrid;
            })
            .or_insert_with(|| (rrf_score, chunk.clone(), SearchSource::Keyword));
    }

    let mut results: Vec<SearchResult> = scores
        .into_values()
        .map(|(score, chunk, source)| SearchResult {
            chunk,
            score,
            source,
        })
        .collect();

    results.sort_by(|a, b| {
        b.score
            .partial_cmp(&a.score)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    results
}

